WITH BASE_RAW AS (
    SELECT
        CC.AL_CODICE AS CD_CONTROPARTE,
        CASE
            WHEN ROW_NUMBER() OVER (
                     PARTITION BY CC.AL_CODICE
                     ORDER BY CC.AL_DATA_MODIFICA, CC.AL_ORA_MODIFICA, CC.ROWID
                 ) = 1
                THEN COALESCE({{ custom_to_timestamp_ntz('CC.AL_DATA_INSERIMENTO') }}, {{ custom_to_timestamp_ntz('CC.AL_DATA_MODIFICA', 'CC.AL_ORA_MODIFICA') }})
            ELSE {{ custom_to_timestamp_ntz('CC.AL_DATA_MODIFICA', 'CC.AL_ORA_MODIFICA') }}
        END AS TS_INIZIO_VALIDITA,
        CC.AL_TIPO_ANAGRAFICA AS TP_CONTROPARTE,
        CC.AL_FORMA_GIURIDICA AS CD_FORMA_GIURIDICA,
        CC.AL_CODICE_FISCALE AS CD_FISCALE,
        CC.AL_CODICE_FISC_CALC AS FL_CF_CALCOLATO,
        CC.AL_CODICE_FISC_FORZ AS FL_CF_FORZATO,
        CC.AL_UTENTE_FORZATURA AS CD_UTENTE_FORZATURA_CF,
        CC.AL_PARTITA_IVA AS CD_PARTITA_IVA,
        CC.AL_NOME AS DS_NOME,
        CC.AL_SECONDO_NOME AS DS_SECONDO_NOME,
        CC.AL_COGNOME AS DS_COGNOME,
        CC.AL_COGNOME_MADRE AS DS_COGNOME_MADRE,
        CC.AL_RIFERIMENTO AS CD_RIFERIMENTO_ALTRA_ANAGRAFICA,
        CC.AL_MATRICOLA AS CD_MATRICOLA,
        CC.AL_RAG_SOCIALE_1 AS DS_RAGIONE_SOCIALE,
        CC.AL_RAG_SOCIALE_2 AS DS_RAGIONE_SOCIALE_2,
        CC.AL_CITTADINANZA AS CD_CITTADINANZA,
        CC.AL_NASCITA_LUOGO AS DS_CITTA_NASCITA,
        CC.AL_NASCITA_NAZIONE AS CD_NAZIONE_NASCITA,
        CC.AL_NASCITA_PROV AS CD_PROVINCIA_NASCITA,
        CC.AL_NASCITA_LUOGO AS DS_COMUNE_NASCITA,
        CC.AL_NASCITA_CAB_LOC AS CD_CAB_COMUNE_NASCITA,
        {{ custom_to_date('CC.AL_NASCITA_DATA') }} AS DT_NASCITA,
        CC.AL_SESSO AS CD_SESSO,
        {{ custom_to_date('CC.AL_DATA_CESSAZIONE') }} AS DT_DECESSO,
        CC.AL_ABI AS CD_ABI,
        CC.AL_COD_IDEN AS CD_IDENTIFICATIVO,
        CC.AL_CODICE_NDG AS CD_NDG,
        CC.AL_CODICE_NDG2 AS CD_NDG2,
        CC.AL_CODICE_NDG3 AS CD_NDG3,
        CC.AL_CODICE_NDG_CRF AS CD_NDG_CRF,
        CC.AL_INPS_MATRICOLA AS CD_INPS_MATRICOLA,
        CC.AL_INAIL_PAT AS CD_INAIL_PAT,
        CC.AL_IPA AS CD_IPA,
        CC.AL_FILIALE AS CD_FILIALE,
        CC.AL_FILIALE_STORICA AS CD_FILIALE_STORICA,
        CC.AL_ESENZIONE_IVA AS CD_ESENZIONE_IVA,
        CC.AL_TIPO_ATTIVITA AS CD_SETTORE_ATTIVITA,
        CC.AL_ATECO AS CD_ATECO,
        CC.AL_RAMOGRUPPO AS CD_RAE,
        CC.AL_SOTTOGRUPPO AS CD_SAE,
        CC.AL_TAE AS CD_TAE,
        CC.AL_NUM_CAMCOMMERCIO AS CD_CCIAA,
        CC.AL_TIPO_CAMCOMMERCIO AS TP_CCIAA,
        CC.AL_PROV_CAMCOMMERCIO AS CD_PROVINCIA_CCIAA,
        {{ custom_to_date('CC.AL_DATA_CAMCOMMERCIO') }}
            AS DT_REGISTRAZIONE_CCIAA,
        CC.AL_CTR_CAMCOMMERCIO AS FL_CONTROLLO_CCIAA,
        CC.AL_FALLIBILE AS FL_FALLIBILE,
        {{ custom_to_date('CC.AL_DATA_FALLIMENTO') }} AS DT_FALLIMENTO,
        CC.AL_PROC_CONCORSUALI AS TP_PROC_CONCORSUALI,
        CC.AL_PROC_LEGALI AS TP_PROC_LEGALI,
        CC.AL_IDE_NUM_DOCUMENTO AS CD_DOCUMENTO,
        CC.AL_IDE_TIPO_DOCUMENTO AS TP_DOCUMENTO,
        CC.AL_IDE_UFFICIO_RILASCIO AS TP_EMITTENTE,
        {{ custom_to_date('CC.AL_IDE_DATA_RILASCIO') }} AS DT_RILASCIO_DOC,
        {{ custom_to_date('CC.AL_IDE_DATA_SCADENZA') }} AS DT_FINE_VALIDITA_DOC,
        CC.AL_IDE_LUOGO_RILASCIO AS DS_COMUNE_RILASCIO_DOC,
        CC.AL_IDE_PROV_RILASCIO AS CD_PROVINCIA_RILASCIO_DOC,
        CC.AL_IDE_NAZIONE_RILASCIO AS CD_NAZIONE_RILASCIO_DOC,
        CC.AL_IDE_NUM2_DOCUMENTO AS CD_DOCUMENTO_2,
        CC.AL_TSA_NUM AS NM_TESSERA_SANITARIA,
        {{ custom_to_date('CC.AL_TSA_DATA_SCADENZA') }}
            AS DT_SCADENZA_TESSERA_SANITARIA,
        CC.AL_IDE_NOTE AS DS_NOTE_DOCUMENTO,
        CC.AL_IDE_UNIV_FORZ AS FL_UNIVOCITA_DOCUMENTO,
        CC.AL_IDE_SOSP_FORZ AS FL_SOSPETTO_FORZATO_DOCUMENTO,
        CC.AL_PRESSO AS DS_PRESSO,
        CC.AL_FRAZIONE AS DS_FRAZIONE,
        CC.AL_INDIRIZZO_1 AS DS_INDIRIZZO_1,
        {{ custom_to_date('CC.AL_INDIR_ATT') }} AS DT_INDIRIZZO_RESIDENZA_DAL,
        CC.AL_INDIRIZZO_2 AS DS_INDIRIZZO_2,
        CC.AL_IND_NORM AS FL_INDIRIZZO_NORMALIZZATO,
        CC.AL_IND_FORZ AS FL_INDIRIZZO_FORZATO,
        CC.AL_CAP AS CD_CAP,
        CC.AL_PROVINCIA AS CD_PROVINCIA_RESIDENZA,
        CC.AL_PAESE_ESTERO AS CD_NAZIONE_RESIDENZA,
        CC.AL_LOCALITA AS DS_COMUNE_RESIDENZA,
        CC.AL_COD_CAB_COMUNE AS CD_CAB_RESIDENZA,
        CC.AL_TIPO_SEDE AS CD_TIPO_SEDE,
        CC.AL_SEDE_INDIRIZZO_1 AS DS_SEDE_INDIRIZZO_1,
        CC.AL_SEDE_INDIRIZZO_2 AS DS_SEDE_INDIRIZZO_2,
        CC.AL_SEDE_IND_NORM AS FL_SEDE_INDIRIZZO_NORMALIZZATO,
        CC.AL_SEDE_IND_FORZ AS FL_SEDE_INDIRIZZO_FORZATO,
        CC.AL_SEDE_PRESSO AS DS_SEDE_PRESSO,
        CC.AL_SEDE_FRAZIONE AS DS_SEDE_FRAZIONE,
        CC.AL_SEDE_PROVINCIA AS CD_SEDE_PROVINCIA,
        CC.AL_SEDE_CAP AS CD_SEDE_CAP,
        CC.AL_SEDE_LOCALITA AS DS_SEDE_COMUNE,
        CC.AL_SEDE_CAB_LOC AS CD_SEDE_CAB_COMUNE,
        CC.AL_SEDE_NAZIONE AS CD_SEDE_NAZIONE,
        CC.AL_PSG_TIPO AS TP_PERMESSO_SOGGIORNO,
        {{ custom_to_date('CC.AL_PSG_SOGGIORNO_DAL') }}
            AS DT_INIZIO_PERMESSO_SOGGIORNO,
        {{ custom_to_date('CC.AL_PSG_DATA_SCADENZA') }}
            AS DT_SCADENZA_PERMESSO_SOGGIORNO,
        CC.AL_PSG_SCAD_FORZ AS FL_SCADENZA_FORZATA_PERMESSO,
        CC.AL_PSG_VAL_FORZ AS FL_VALIDITA_FORZATA_PERMESSO,
        CC.AL_TELEFONO_CEL AS NM_CELLULARE,
        CC.AL_TELEFONO AS NM_TELEFONO,
        CC.AL_TELEFONO_2 AS NM_TELEFONO_UFFICIO,
        CC.AL_TELEFONO_SEDE AS NM_TELEFONO_SEDE,
        CC.AL_FAX AS DS_FAX,
        CC.AL_EMAIL AS DS_EMAIL,
        CC.AL_EMAIL_PEC AS DS_EMAIL_PEC,
        CC.AL_POSIZIONE AS CD_OCCUPAZIONE,
        CC.AL_OCC_OCCUPAZIONE AS CD_OCCUPAZIONE_2,
        {{ custom_to_date('CC.AL_DATA_POSIZIONE') }} AS DT_OCCUPAZIONE,
        CC.AL_OCC_TIPO_ATTIVITA AS CD_TIPO_ATTIVITA_OCCUPAZIONE,
        CC.AL_OCC_SETTORE AS CD_SETTORE_OCCUPAZIONE,
        {{ custom_to_date('CC.AL_DL_OCCUPAZIONE_DAL') }}
            AS DT_INIZIO_OCCUPAZIONE_CLI,
        {{ custom_to_date('CC.AL_DL_OCCUPAZIONE_AL') }}
            AS DT_FINE_OCCUPAZIONE_CLI,
        CC.AL_ST_FLAG_ALBO_ARTIG AS FL_ISCRITTO_ALBO_ARTIGIANI,
        CC.AL_ST_NUM_DIPENDENTI AS NM_DIPENDENTI,
        CC.AL_CAPITALE_SOCIALE AS NM_CAPITALE_SOCIALE,
        CC.AL_PARTEC_ENTE_PUB AS FL_PARTECIPATA_ENTE_PUBBLICO,
        CC.AL_DL_DENOMINAZIONE AS DS_DATORE_LAVORO,
        CC.AL_DL_CODICE_FISCALE AS CD_FISCALE_DATORE_LAVORO,
        CC.AL_DL_PARTITA_IVA AS CD_PARTITA_IVA_DATORE_LAVORO,
        CC.AL_DL_FORMA_GIURIDICA AS CD_FORMA_GIURIDICA_DATORE_LAVORO,
        CC.AL_DL_COD_IDEN AS CD_IDEN_DATORE_LAVORO,
        CC.AL_DL_INDIRIZZO AS DS_INDIRIZZO_DATORE_LAVORO,
        CC.AL_DL_PRESSO AS DS_PRESSO_DATORE_LAVORO,
        CC.AL_DL_LOCALITA AS DS_COMUNE_DATORE_LAVORO,
        CC.AL_DL_CAP AS CD_CAP_INDIRIZZO_DATORE_LAVORO,
        CC.AL_DL_FRAZIONE AS DS_FRAZIONE_DATORE_LAVORO,
        CC.AL_DL_PROVINCIA AS CD_PROVINCIA_DATORE_LAVORO,
        CC.AL_DL_TELEFONO AS NM_TELEFONO_DATORE_LAVORO,
        CC.AL_DL_IND_NORM AS FL_INDIRIZZO_NORMALIZZATO_DATORE_LAVORO,
        CC.AL_DL_IND_FORZ AS FL_INDIRIZZO_FORZATO_DATORE_LAVORO,
        CC.AL_DL_FAX AS DS_FAX_DATORE_LAVORO,
        CC.AL_TIPO_CONTROPARTE_19 AS FL_DIPENDENTE,
        CC.AL_TIPO_CONTROPARTE_01 AS FL_CLIENTE,
        CC.AL_TIPO_CONTROPARTE_02 AS FL_AGENTE,
        CC.AL_TIPO_CONTROPARTE_03 AS FL_TIPO_ALTRO,
        CC.AL_TIPO_CONTROPARTE_04 AS FL_GARANTE,
        CC.AL_TIPO_CONTROPARTE_06 AS FL_FORNITORE,
        CC.AL_TIPO_CONTROPARTE_11 AS FL_COOBLIGATO,
        CC.AL_TIPO_CONTROPARTE_12 AS FL_CONVENZIONATO,
        CC.AL_TIPO_CONTROPARTE_13 AS FL_DITTA,
        CC.AL_TIPO_CONTROPARTE_14 AS FL_FIRMATARIO,
        CC.AL_TIPO_CONTROPARTE_16 AS FL_DELEGATO,
        CC.AL_TIPO_CONTROPARTE_17 AS FL_FONDO_PENSIONE,
        CC.AL_TIPO_CONTROPARTE_18 AS FL_FINANZIARIA,
        CC.AL_TIPO_CONTROPARTE_21 AS FL_DATORE_LAVORO,
        CC.AL_INTERM_ABILITATO AS TP_INTERMEDIARIO_ABILITATO,
        CC.AL_ANA_DI_GRUPPO AS FL_ANA_DI_GRUPPO,
        CC.AL_CLIENTE_BANCA AS FL_CLIENTE_BANCA,
        CC.AL_RILEV_QUALITA AS TP_CONSENSO_SRQ,
        CC.AL_OFF_COMM_INTERNE AS TP_CONSENSO_OCI,
        CC.AL_OFF_COMM_INT_AUT AS TP_CONSENSO_OIA,
        CC.AL_OFF_COMM_ESTERNE AS TP_CONSENSO_OCE,
        CC.AL_OFF_COMM_EST_AUT AS TP_CONSENSO_OEA,
        CC.AL_SERVIZI_ALTRI AS TP_CONSENSO_OSA,
        CC.AL_DATI_SENSIBILI AS TP_CONSENSO_DSU,
        CC.AL_CONS_INFO_SIC AS TP_CONSENSO_SIC,
        CC.AL_ISTRUTT_PRATICHE AS TP_CONSENSO_IPR,
        {{ custom_to_date('CC.AL_DT_PRIVACY_ISTRUTT') }} AS DT_CONSENSO_IPR,
        {{ custom_to_date('CC.AL_DT_RILEV_QUALITA') }} AS DT_CONSENSO_SRQ,
        {{ custom_to_date('CC.AL_DT_PRIVACY_OFFERTE') }} AS DT_CONSENSO_OCI,
        {{ custom_to_date('CC.AL_DT_OFF_COMM_INT_AUT') }} AS DT_CONSENSO_OIA,
        {{ custom_to_date('CC.AL_DT_OFF_COMM_ESTERNE') }} AS DT_CONSENSO_OCE,
        {{ custom_to_date('CC.AL_DT_OFF_COMM_EST_AUT') }} AS DT_CONSENSO_OEA,
        {{ custom_to_date('CC.AL_DT_SERVIZI_ALTRI') }} AS DT_CONSENSO_OSA,
        {{ custom_to_date('CC.AL_DT_PRIVACY_SENSIBILI') }} AS DT_CONSENSO_DSU,
        {{ custom_to_date('CC.AL_DATA_CONS_INFO_SIC') }} AS DT_CONSENSO_CIS,
        CC.AL_NOTE_CONS_INFO_SIC AS DS_NOTE_SIC,
        CC.AL_PRIVACY_RICH_CANC AS TP_CANCELLAZIONE_DATI_PRIVACY,
        {{ custom_to_decimal('CC.AL_RED_REDDITO', 13, 2) }} AS EU_REDDITO_ANNUO,
        CC.AL_RED_NUM_MENSILITA AS NM_MENSILITA_REDDITO,
        {{ custom_to_decimal('CC.AL_RED_ALTRI_REDDITI', 13, 2) }}
            AS EU_ALTRI_REDDITI,
        CC.AL_RED_TIPO AS TP_REDDITO,
        {{ custom_to_decimal('CC.AL_RED_REDDITO_FAM', 13, 2) }}
            AS EU_REDDITO_FAMILIARE,
        {{ custom_to_decimal('CC.AL_RED_REDDITO_FAM_C', 13, 2) }}
            AS EU_REDDITO_FAMILIARE_CONIUGE,
        CC.AL_IN_CODICE_CR AS CD_CENTRALE_RISCHI,
        CC.AL_IN_CODICE_SIA AS CD_SIA,
        CC.AL_LEG_CODICE AS CD_LEGALE_RAPPRESENTANTE,
        CC.AL_LEG_NOME AS DS_NOME_LEGALE_RAPPRESENTANTE,
        CC.AL_LEG_INDIRIZZO AS DS_INDIRIZZO_LEGALE_RAPPRESENTANTE,
        CC.AL_LEG_PRESSO AS DS_PRESSO_LEGALE_RAPPRESENTANTE,
        CC.AL_LEG_CAP AS CD_CAP_LEGALE_RAPPRESENTANTE,
        CC.AL_LEG_FRAZIONE AS DS_FRAZIONE_LEGALE_RAPPRESENTANTE,
        CC.AL_LEG_LOCALITA AS DS_COMUNE_LEGALE_RAPPRESENTANTE,
        CC.AL_LEG_PROVINCIA AS CD_PROVINCIA_LEGALE_RAPPRESENTANTE,
        {{ custom_to_date('CC.AL_LEG_DATA_NASCITA') }}
            AS DT_NASCITA_LEGALE_RAPPRESENTANTE,
        CC.AL_LEG_LUOGO_NASCITA AS DS_LOUGO_NASCITA_LEGALE_RAPPRESENTANTE,
        CC.AL_LEG_PROV_NASCITA AS CD_PROVINCIA_NASCITA_LEGALE_RAPPRESENTANTE,
        CC.AL_LEG_NAZ_NASCITA AS CD_NAZIONE_NASCITA_LEGALE_RAPPRESENTANTE,
        CC.AL_LEG_CITTADINANZA AS CD_CITTADINANZA_LEGALE_RAPPRESENTANTE,
        CC.AL_CAUSALE_ANNULLO AS CD_CAUSALE_ANNULLO,
        {{ custom_to_date('CC.AL_DATA_ANNULLO') }} AS DT_ANNULLO,
        {{ custom_to_date('CC.AL_DATA_INSERIMENTO') }} AS DT_INSERIMENTO,
        CC.AL_UTENTE_INSERIMENTO AS CD_UTENTE_INSERIMENTO,
        {{ custom_to_date('CC.AL_DATA_VARIAZIONE') }} AS DT_VARIAZIONE,
        CC.AL_UTENTE_VARIAZIONE AS CD_UTENTE_VARIAZIONE,
        {{ custom_to_date('CC.AL_DATA_TRASMISSIONE') }} AS DT_TRASMISSIONE,
        CC.AL_RICER_1 AS DS_STRINGA_RICERCA,
        CC.AL_USER_1 AS CD_USER_1,
        CC.AL_USER_2 AS CD_USER_2,
        CC.AL_USER_3 AS CD_USER_3,
        CC.AL_NORMALIZZATO_RAG AS FL_NORM_DENOMINAZIONE,
        CC.AL_NORMALIZZATO_LOC AS FL_NORM_LOCALITA,
        CC.AL_NORMALIZZATO_IND AS FL_NORM_INDIRIZZO,
        CC.AL_NOTA_01 AS DS_NOTA_01,
        CC.AL_NOTA_02 AS DS_NOTA_02,
        CC.AL_FIL_CASELLA_POSTALE AS CD_FILIALE_CASELLA_POSTALE,
        CC.AL_NUM_CASELLA_POSTALE AS NM_CASELLA_POSTALE,
        CC.LASTMODIFIEDDATA,
        ROW_NUMBER() OVER (
            PARTITION BY CC.AL_CODICE, CC.AL_DATA_MODIFICA, CC.AL_ORA_MODIFICA
            ORDER BY CC.ROWID
        )::NUMBER(38, 0) AS PR_PK
    FROM {{ ref('ccanalog') }} AS CC
    WHERE CC.FL_DELETED = 'N'
),

-- TS_INIZIO_VALIDITA in BASE_RAW contiene gia' una window function (ROW_NUMBER, per il CASE
-- del primo record storico): calcolare TS_FINE_VALIDITA con LEAD(...) OVER (...) nella STESSA
-- SELECT annullerebbe una window function dentro l'altra ("window function may not be nested
-- inside another window function"). Rilette qui come colonne semplici da una CTE separata,
-- cosi' TS_FINE_VALIDITA e' un solo livello di window function.
BASE AS (
    SELECT
        B.CD_CONTROPARTE,
        B.TS_INIZIO_VALIDITA,
        B.TP_CONTROPARTE,
        B.CD_FORMA_GIURIDICA,
        B.CD_FISCALE,
        B.FL_CF_CALCOLATO,
        B.FL_CF_FORZATO,
        B.CD_UTENTE_FORZATURA_CF,
        B.CD_PARTITA_IVA,
        B.DS_NOME,
        B.DS_SECONDO_NOME,
        B.DS_COGNOME,
        B.DS_COGNOME_MADRE,
        B.CD_RIFERIMENTO_ALTRA_ANAGRAFICA,
        B.CD_MATRICOLA,
        B.DS_RAGIONE_SOCIALE,
        B.DS_RAGIONE_SOCIALE_2,
