        B.CD_ESENZIONE_IVA,
        B.CD_SETTORE_ATTIVITA,
        B.CD_ATECO,
        B.CD_RAE,
        B.CD_SAE,
        B.CD_TAE,
        B.CD_CCIAA,
        B.TP_CCIAA,
        B.CD_PROVINCIA_CCIAA,
        B.DT_REGISTRAZIONE_CCIAA,
        B.FL_CONTROLLO_CCIAA,
        B.FL_FALLIBILE,
        B.DT_FALLIMENTO,
        B.TP_PROC_CONCORSUALI,
        B.TP_PROC_LEGALI,
        B.CD_DOCUMENTO,
        B.TP_DOCUMENTO,
        B.TP_EMITTENTE,
        B.DT_RILASCIO_DOC,
        B.DT_FINE_VALIDITA_DOC,
