        B.DS_FRAZIONE,
        B.DS_INDIRIZZO_1,
        B.DT_INDIRIZZO_RESIDENZA_DAL,
        B.DS_INDIRIZZO_2,
        B.FL_INDIRIZZO_NORMALIZZATO,
        B.FL_INDIRIZZO_FORZATO,
