        B.DS_SEDE_PRESSO,
        B.DS_SEDE_FRAZIONE,
        B.CD_SEDE_PROVINCIA,
        B.CD_SEDE_CAP,
        B.DS_SEDE_COMUNE,
        B.CD_SEDE_CAB_COMUNE,
        B.CD_SEDE_NAZIONE,
        B.TP_PERMESSO_SOGGIORNO,
