        B.FL_INDIRIZZO_FORZATO_DATORE_LAVORO,
        B.DS_FAX_DATORE_LAVORO,
        B.FL_DIPENDENTE,
        B.FL_CLIENTE,
        B.FL_AGENTE,
        B.FL_TIPO_ALTRO,
        B.FL_GARANTE,
        B.FL_FORNITORE,
        B.FL_COOBLIGATO,
        B.FL_CONVENZIONATO,
