{% if is_incremental() %}
, OLD_PROGRESSIVO AS (
    SELECT
        CD_CONTROPARTE,
        MAX(PR_CONTROPARTE) AS OLD_PROGRESSIVO,
        MAX(TS_INIZIO_VALIDITA) AS OLD_TS_INIZIO_VALIDITA
    FROM {{ this }}
    GROUP BY CD_CONTROPARTE
)
{% endif %}

SELECT
    D.CD_CONTROPARTE,
    D.TS_INIZIO_VALIDITA,
    {{ ts_fine_validita('D.CD_CONTROPARTE', 'D.TS_INIZIO_VALIDITA', order_extra='D.PR_PK') }}
        AS TS_FINE_VALIDITA,
    D.PR_PK,
    {% if is_incremental() %}
    COALESCE(
        CASE WHEN D.TS_INIZIO_VALIDITA <= OP.OLD_TS_INIZIO_VALIDITA THEN OP.OLD_PROGRESSIVO END,
        COALESCE(OP.OLD_PROGRESSIVO, 0)
            + ROW_NUMBER() OVER (
                PARTITION BY D.CD_CONTROPARTE, (D.TS_INIZIO_VALIDITA <= OP.OLD_TS_INIZIO_VALIDITA)
                ORDER BY D.TS_INIZIO_VALIDITA, D.PR_PK
            )
    )::NUMBER(38, 0)
    {% else %}
    (
        ROW_NUMBER() OVER (
            PARTITION BY D.CD_CONTROPARTE
            ORDER BY D.TS_INIZIO_VALIDITA, D.PR_PK
        )
    )::NUMBER(38, 0)
    {% endif %} AS PR_CONTROPARTE,
    D.TP_CONTROPARTE,
