FROM DEDUP AS D
{%- if is_incremental() %}
LEFT JOIN OLD_PROGRESSIVO AS OP ON OP.CD_CONTROPARTE = D.CD_CONTROPARTE
{%- endif %}
LEFT JOIN {{ ref('cccretci') }} AS CI1
    ON
        D.CD_CITTADINANZA = CI1.CRECI_CITTADINANZA
        AND D.TS_INIZIO_VALIDITA >= CI1.TS_INIZIO_VALIDITA
        AND D.TS_INIZIO_VALIDITA < CI1.TS_FINE_VALIDITA
        AND CI1.FL_DELETED = 'N'
LEFT JOIN {{ ref('ccanatna') }} AS NA1
    ON
        D.CD_NAZIONE_NASCITA = NA1.ANATNA_NAZIONE
        AND D.TS_INIZIO_VALIDITA >= NA1.TS_INIZIO_VALIDITA
        AND D.TS_INIZIO_VALIDITA < NA1.TS_FINE_VALIDITA
        AND NA1.FL_DELETED = 'N'
LEFT JOIN {{ ref('ccanatpr') }} AS PR1
    ON
        D.CD_PROVINCIA_NASCITA = PR1.ANATPR_PROVINCIA
        AND D.TS_INIZIO_VALIDITA >= PR1.TS_INIZIO_VALIDITA
        AND D.TS_INIZIO_VALIDITA < PR1.TS_FINE_VALIDITA
        AND PR1.FL_DELETED = 'N'
LEFT JOIN {{ ref('ccanatat') }} AS AT1
    ON
        D.CD_ATECO = AT1.ANATAT_ATECO
        AND D.TS_INIZIO_VALIDITA >= AT1.TS_INIZIO_VALIDITA
        AND D.TS_INIZIO_VALIDITA < AT1.TS_FINE_VALIDITA
        AND AT1.FL_DELETED = 'N'
LEFT JOIN {{ ref('ccanatra') }} AS RA1
    ON
        D.CD_RAE = RA1.ANATRA_RAE
        AND D.TS_INIZIO_VALIDITA >= RA1.TS_INIZIO_VALIDITA
        AND D.TS_INIZIO_VALIDITA < RA1.TS_FINE_VALIDITA
        AND RA1.FL_DELETED = 'N'
LEFT JOIN {{ ref('ccanatsa') }} AS SA1
    ON
        D.CD_SAE = SA1.ANATSA_SAE
        AND D.TS_INIZIO_VALIDITA >= SA1.TS_INIZIO_VALIDITA
        AND D.TS_INIZIO_VALIDITA < SA1.TS_FINE_VALIDITA
        AND SA1.FL_DELETED = 'N'
LEFT JOIN {{ ref('ccanatpr') }} AS PR2
    ON
        D.CD_PROVINCIA_CCIAA = PR2.ANATPR_PROVINCIA
        AND D.TS_INIZIO_VALIDITA >= PR2.TS_INIZIO_VALIDITA
        AND D.TS_INIZIO_VALIDITA < PR2.TS_FINE_VALIDITA
        AND PR2.FL_DELETED = 'N'
LEFT JOIN {{ ref('ccanatpr') }} AS PR3
    ON
        D.CD_PROVINCIA_RILASCIO_DOC = PR3.ANATPR_PROVINCIA
        AND D.TS_INIZIO_VALIDITA >= PR3.TS_INIZIO_VALIDITA
        AND D.TS_INIZIO_VALIDITA < PR3.TS_FINE_VALIDITA
        AND PR3.FL_DELETED = 'N'
LEFT JOIN {{ ref('ccanatna') }} AS NA2
    ON
        D.CD_NAZIONE_RILASCIO_DOC = NA2.ANATNA_NAZIONE
        AND D.TS_INIZIO_VALIDITA >= NA2.TS_INIZIO_VALIDITA
        AND D.TS_INIZIO_VALIDITA < NA2.TS_FINE_VALIDITA
        AND NA2.FL_DELETED = 'N'
LEFT JOIN {{ ref('ccanatpr') }} AS PR4
    ON
        D.CD_PROVINCIA_RESIDENZA = PR4.ANATPR_PROVINCIA
        AND D.TS_INIZIO_VALIDITA >= PR4.TS_INIZIO_VALIDITA
        AND D.TS_INIZIO_VALIDITA < PR4.TS_FINE_VALIDITA
        AND PR4.FL_DELETED = 'N'
LEFT JOIN {{ ref('ccanatre') }} AS RE1
    ON
        PR4.ANATPR_REGIONE = RE1.ANATRE_REGIONE
        AND D.TS_INIZIO_VALIDITA >= RE1.TS_INIZIO_VALIDITA
        AND D.TS_INIZIO_VALIDITA < RE1.TS_FINE_VALIDITA
        AND RE1.FL_DELETED = 'N'
LEFT JOIN {{ ref('ccanatna') }} AS NA3
    ON
        D.CD_NAZIONE_RESIDENZA = NA3.ANATNA_NAZIONE
        AND D.TS_INIZIO_VALIDITA >= NA3.TS_INIZIO_VALIDITA
        AND D.TS_INIZIO_VALIDITA < NA3.TS_FINE_VALIDITA
        AND NA3.FL_DELETED = 'N'
LEFT JOIN {{ ref('ccanatpr') }} AS PR5
    ON
        D.CD_SEDE_PROVINCIA = PR5.ANATPR_PROVINCIA
        AND D.TS_INIZIO_VALIDITA >= PR5.TS_INIZIO_VALIDITA
        AND D.TS_INIZIO_VALIDITA < PR5.TS_FINE_VALIDITA
        AND PR5.FL_DELETED = 'N'
LEFT JOIN {{ ref('ccanatre') }} AS RE2
    ON
        PR5.ANATPR_REGIONE = RE2.ANATRE_REGIONE
        AND D.TS_INIZIO_VALIDITA >= RE2.TS_INIZIO_VALIDITA
        AND D.TS_INIZIO_VALIDITA < RE2.TS_FINE_VALIDITA
        AND RE2.FL_DELETED = 'N'
LEFT JOIN {{ ref('ccanatna') }} AS NA4
    ON
        D.CD_SEDE_NAZIONE = NA4.ANATNA_NAZIONE
        AND D.TS_INIZIO_VALIDITA >= NA4.TS_INIZIO_VALIDITA
        AND D.TS_INIZIO_VALIDITA < NA4.TS_FINE_VALIDITA
        AND NA4.FL_DELETED = 'N'
LEFT JOIN {{ ref('ccanatpo') }} AS PO1
    ON
        D.CD_OCCUPAZIONE = PO1.ANATPO_POSIZ_CONTROP
        AND D.TS_INIZIO_VALIDITA >= PO1.TS_INIZIO_VALIDITA
        AND D.TS_INIZIO_VALIDITA < PO1.TS_FINE_VALIDITA
        AND PO1.FL_DELETED = 'N'
LEFT JOIN {{ ref('ccanatpr') }} AS PR6
    ON
        D.CD_PROVINCIA_DATORE_LAVORO = PR6.ANATPR_PROVINCIA
        AND D.TS_INIZIO_VALIDITA >= PR6.TS_INIZIO_VALIDITA
        AND D.TS_INIZIO_VALIDITA < PR6.TS_FINE_VALIDITA
        AND PR6.FL_DELETED = 'N'
LEFT JOIN {{ ref('ccanatpr') }} AS PR7
    ON
        D.CD_PROVINCIA_LEGALE_RAPPRESENTANTE = PR7.ANATPR_PROVINCIA
        AND D.TS_INIZIO_VALIDITA >= PR7.TS_INIZIO_VALIDITA
        AND D.TS_INIZIO_VALIDITA < PR7.TS_FINE_VALIDITA
        AND PR7.FL_DELETED = 'N'
LEFT JOIN {{ ref('ccanatpr') }} AS PR8
    ON
        D.CD_PROVINCIA_NASCITA_LEGALE_RAPPRESENTANTE = PR8.ANATPR_PROVINCIA
        AND D.TS_INIZIO_VALIDITA >= PR8.TS_INIZIO_VALIDITA
        AND D.TS_INIZIO_VALIDITA < PR8.TS_FINE_VALIDITA
        AND PR8.FL_DELETED = 'N'
LEFT JOIN {{ ref('ccanatna') }} AS NA5
    ON
        D.CD_NAZIONE_NASCITA_LEGALE_RAPPRESENTANTE = NA5.ANATNA_NAZIONE
        AND D.TS_INIZIO_VALIDITA >= NA5.TS_INIZIO_VALIDITA
        AND D.TS_INIZIO_VALIDITA < NA5.TS_FINE_VALIDITA
        AND NA5.FL_DELETED = 'N'
LEFT JOIN {{ ref('cccretci') }} AS CI2
    ON
        D.CD_CITTADINANZA_LEGALE_RAPPRESENTANTE = CI2.CRECI_CITTADINANZA
        AND D.TS_INIZIO_VALIDITA >= CI2.TS_INIZIO_VALIDITA
        AND D.TS_INIZIO_VALIDITA < CI2.TS_FINE_VALIDITA
        AND CI2.FL_DELETED = 'N'
